        name: "Arrow IV - Homing Ammo (C)",
        altNames: ["Arrow IV Guided Missile", "Arrow IV TAG Missile", "Homing Arrow Ammo", "Ammo (Arrow IV (Homing))"],
        tag: "ammo-clan-arrow-iv-homing",
