        page: 185,
        alphaStrike: { specialAbility: ["LRM#/#/#/#", "IF#", "MEL#"], heat: 0, rangeShort: 0, rangeMedium: 0, rangeLong: 0, rangeExtreme: 0, tc: false, notes: [] },
        introducedInEdition: "battletech-compendium", editionStats: { "battletech-compendium": { book: "BTC", page: 121, name: "Thunder LRM", weight: 1, cbills: 60000, notes: "Thunder LRMs: attack a hex and lay a conventional minefield equal in strength to the missiles in the attack, 20 points at most in a hex; bought by the full ton. No help from Artemis or Narc (BTC p.121). The price list prints \"2 x normal\" (BTC p.129). \"Thunder\" is the Inner Sphere name for FASCAM; the Clans use a warhead that is virtually identical." }, "compendium-rules-of-warfare": { book: "BTC:RoW", page: 121, name: "Thunder LRM", weight: 1, cbills: 60000, notes: "Thunder is the Inner Sphere name for FASCAM; the Clans use a virtually identical warhead. Attacks a hex and scatters like artillery on a miss: the hex becomes a conventional minefield whose Damage Value is the number of missiles fired, 20 from an LRM-20 and 5 from an LRM-5. Fields in one hex add up to a Damage Value of 20 at most. No command-detonated or vibrabomb fields, and no Artemis IV or Narc benefit. Carried in full-ton lots; costs twice as much as standard rounds (BTC:RoW p.121): 2 x normal on the price list (BTC:RoW p.124)." }, "master-rules": { book: "BMR", page: 132, name: "Thunder LRM", weight: 1, cbills: 60000, notes: "Attacks a hex and scatters like artillery on a miss: the hex becomes a conventional minefield whose Damage Value is the launcher's size, 15 from an LRM-15 and 5 from an LRM-5. Fields in one hex add up to a Damage Value of 20 at most. No command-detonated or vibrabomb fields (BMR p.132). 2 x normal on the price list (BMR p.138). Special munitions go in standard LRM or SRM launchers only, in full-ton lots, and a launcher combines no more than one special munition or property (BMR p.130)." }, "master-rules-revised": { book: "BMR(R)", page: 144, name: "Thunder LRM", weight: 1, cbills: 60000, notes: "Attacks a hex and scatters like artillery on a miss: the hex becomes a conventional minefield whose Damage Value is the launcher's size, 15 from an LRM-15 and 5 from an LRM-5. Fields in one hex add up to a Damage Value of 20 at most. A unit in the hex when it is mined may leave safely. No command-detonated or vibrabomb fields (BMR(R) p.144). 2 x normal on the price list (BMR(R) p.151). Special munitions go in standard LRM or SRM launchers only, in full-ton lots, and a launcher combines no more than one special munition or property (BMR(R) p.141)." } },
