        page: 173,
        alphaStrike: { specialAbility: [], heat: 0, rangeShort: 0, rangeMedium: 0, rangeLong: 0, rangeExtreme: 0, tc: false, notes: [] },
        notes: "Douses non-Inferno fires on 4+ (Inferno fires on 12) and cools a heat-tracking target by 3 points a hit (at most 9 a turn); 1-point ballistic damage to conventional infantry. Also fired by Vehicle and Heavy Flamers (their own coolant records). Early spaceflight, stored as 2100. Full-ton lots; a Sprayer gets half the shots (TO:AUE p.173). Cost 3,000 C-bills a ton, ammo per ton x1 (TO:AUE p.227); ammo BV 1, as the standard round (TO:AUE p.194).",
